        period, unit = {"a": ("annual", "yuan per year"), "b": ("monthly", "yuan per month"), "c": ("percentage", "percent of reported wage")}[unit_part]
        add(rec, f"personal_wage_deduction_total_{period}", f"Total personal wage deductions ({period})", "reported total wage deductions", caveat + " Conditional on wage-reporting scope and the format selector; includes personal income tax, insurance, housing fund and other fees as asked in the wave questionnaire. Keep annual, monthly and percentage responses separate. Amounts are nominal; inflation adjustment is needed for cross-wave currency comparisons.", "official questionnaire unit and amount fields reviewed; special response codes pending respondent-data validation", unit)
